<?php require '../../../config/bootstrap.php';rate_limit('iot_telemetry',300,60);$key=$_SERVER['HTTP_X_DEVICE_KEY']??'';$d=request_json();$code=trim((string)($d['device_code']??''));if($key===''||$code==='')json_response(['error'=>'Credenciais do dispositivo ausentes'],401);$hash=hash_hmac('sha256',$key,envv('DEVICE_KEY_PEPPER','change-me'));$s=db()->prepare('SELECT d.*,c.secret_hash FROM devices d JOIN device_credentials c ON c.device_id=d.id AND c.active=1 WHERE d.device_code=? LIMIT 1');$s->execute([$code]);$dev=$s->fetch();if(!$dev||!hash_equals($dev['secret_hash'],$hash))json_response(['error'=>'Dispositivo não autorizado'],401);$v=fn($k,$min,$max)=>isset($d[$k])?max($min,min($max,(float)$d[$k])):null;$s=db()->prepare('INSERT INTO telemetry(tenant_id,device_id,temperature,humidity,feed_level_kg,water_level_pct,battery_voltage,raw_payload,recorded_at,received_at) VALUES(?,?,?,?,?,?,?,?,COALESCE(?,NOW()),NOW())');$s->execute([$dev['tenant_id'],$dev['id'],$v('temperature',-50,100),$v('humidity',0,100),$v('feed_level_kg',0,100000),$v('water_level_pct',0,100),$v('battery_voltage',0,100),json_encode($d,JSON_UNESCAPED_UNICODE),$d['recorded_at']??null]);db()->prepare('UPDATE devices SET last_seen_at=NOW() WHERE id=?')->execute([$dev['id']]);json_response(['ok'=>true,'received_at'=>date('c')]);
